/* Название на сайте: type + своё название RICCA или «№ NN» из id. short — подпись в сетке категории;
   reading — чтение названия кириллицей для текста WhatsApp (пусто, если названия или чтения нет). */
(function () {
  var own = window.RICCA_MODEL_NAMES || {}, rd = window.RICCA_MODEL_READINGS || {};
  window.RICCA_CATALOG.forEach(function (it) {
    var n = String(own[it.id] || '').trim();
    it.short = n || '№\u00A0' + it.id.split('-').pop();
    it.name = it.type + ' ' + it.short;
    it.reading = n ? String(rd[n] || '').trim() : '';
  });
})();

